export const envelope = [38, 16, 15];

export default function build(api) {
  const [W, H, D] = api.size;

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  const wood = api.theme.wood || {};
  const stone = api.theme.stone || {};
  const ground = api.theme.ground || {};

  function cleanId(b, fallback) {
    if (!b) return fallback;
    return b.split('[')[0];
  }

  const logId = cleanId(wood.log, "minecraft:spruce_log");
  const strippedId = cleanId(wood.stripped, "minecraft:stripped_spruce_log");
  const planksId = cleanId(wood.planks, "minecraft:spruce_planks");
  const stairsId = cleanId(wood.stairs, "minecraft:spruce_stairs");
  const slabId = cleanId(wood.slab, "minecraft:spruce_slab");
  const fenceId = cleanId(wood.fence, "minecraft:spruce_fence");
  const trapdoorId = cleanId(wood.trapdoor, "minecraft:spruce_trapdoor");

  const stoneSlabId = cleanId(stone.slab, "minecraft:stone_slab");
  const stoneWallId = cleanId(stone.wall, "minecraft:cobblestone_wall");

  function logX() { return `${logId}[axis=x]`; }
  function logY() { return `${logId}[axis=y]`; }
  function logZ() { return `${logId}[axis=z]`; }

  function strippedX() { return `${strippedId}[axis=x]`; }
  function strippedY() { return `${strippedId}[axis=y]`; }
  function strippedZ() { return `${strippedId}[axis=z]`; }

  function stair(facing, half = 'bottom', shape = 'straight') {
    return `${stairsId}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function sl(type = 'bottom') {
    return `${slabId}[type=${type}]`;
  }

  function td(facing = 'north', half = 'bottom', open = false) {
    return `${trapdoorId}[facing=${facing},half=${half},open=${open}]`;
  }

  const SEAT_Y = 4;

  function getGroundY(x, z) {
    const h = api.heightAt(x, z);
    const gy = SEAT_Y + Math.round(h);
    return Math.max(0, Math.min(H - 1, gy));
  }

  // ==========================================
  // 1. MASSIVE STUMP & BUTTRESS BASE (x: 0..6)
  // ==========================================
  const stumpCX = 3.5;
  const stumpCZ = 7.0;

  for (let x = 0; x <= 6; x++) {
    for (let z = 2; z <= 12; z++) {
      const dx = x - stumpCX;
      const dz = z - stumpCZ;
      const dist = Math.hypot(dx, dz);
      const theta = Math.atan2(dz, dx);
      const flutes = 0.65 * Math.cos(4 * theta) + 0.35 * Math.sin(2 * theta + 0.5);
      const baseR = 3.35 + flutes;

      if (dist <= baseR + 0.45) {
        const gY = getGroundY(x, z);
        let topY = 9;
        if (dist > 2.5) {
          topY = Math.max(gY, Math.min(9, Math.round(9 - (dist - 2.5) * 2.1)));
        }

        for (let y = gY; y <= topY; y++) {
          // Logger's face cut (undercut wedge) on East side toward fell direction
          const isFaceCut = (x >= 4 && y >= 6 && y <= 8 && Math.abs(dz) <= 1.5 && (y - 6 <= (x - 3.8) * 1.6));
          if (isFaceCut) {
            if (y === 6) {
              set(x, y, z, strippedY());
            } else if (x === 4) {
              set(x, y, z, stair('west', 'top'));
            }
            continue;
          }

          // Backcut kerf gap on West side
          const isBackCut = (x <= 2 && y === 8 && Math.abs(dz) <= 1.7);
          if (isBackCut) {
            set(x, y, z, strippedY());
            continue;
          }

          // Stump mass
          if (dist >= baseR - 0.7 || (dist > 2.2 && y < 8)) {
            set(x, y, z, logY());
          } else {
            set(x, y, z, (y === topY) ? strippedY() : planksId);
          }
        }
      }
    }
  }

  // Splintered holding wood (hinge fibers) sticking up from stump
  set(5, 9, 6, strippedY());
  set(5, 10, 6, fenceId);
  set(5, 9, 7, strippedY());
  set(5, 10, 7, strippedY());
  set(5, 11, 7, fenceId);
  set(5, 9, 8, strippedY());
  set(5, 10, 8, fenceId);
  set(4, 9, 7, stair('east', 'bottom'));

  // Rigid trunk butt connection (ensuring 6-connectivity)
  set(6, 8, 7, strippedX());
  set(6, 7, 6, logX());
  set(6, 7, 7, logX());
  set(6, 7, 8, logX());
  set(6, 8, 6, strippedX());
  set(6, 8, 8, strippedX());

  // Springboards on stump notches
  // North springboard
  set(3, 7, 5, strippedY());
  set(3, 7, 4, planksId);
  set(3, 7, 3, sl('bottom'));
  set(3, 8, 3, td('north', 'bottom', false));
  set(3, 9, 3, "minecraft:lantern[hanging=false]");

  // South springboard
  set(3, 7, 9, strippedY());
  set(3, 7, 10, planksId);
  set(3, 7, 11, sl('bottom'));
  set(3, 8, 11, td('south', 'bottom', false));

  // West backcut board
  set(1, 8, 7, strippedY());
  set(0, 8, 7, sl('top'));
  set(0, 9, 7, fenceId);

  // ==========================================
  // 2. THE FALLEN COLOSSAL TRUNK (x: 7..36)
  // ==========================================
  const logCY = 8.0;
  const logCZ = 7.0;

  for (let x = 7; x <= 36; x++) {
    const t = (x - 7) / 29.0;
    const r = 3.35 - 0.45 * t;

    for (let y = 5; y <= 11; y++) {
      for (let z = 4; z <= 10; z++) {
        const dy = y - logCY;
        const dz = z - logCZ;
        const dist = Math.hypot(dy, dz);

        if (dist <= r) {
          // Kerf 1 at x = 18
          if (x === 18) {
            if (y >= 7) continue; // slot gap for crosscut saw
            if (y === 6) {
              set(x, y, z, strippedX());
              continue;
            }
          }

          // Kerf 2 at x = 28
          if (x === 28) {
            if (y >= 7) continue; // slot gap
            if (y === 6) {
              set(x, y, z, strippedX());
              continue;
            }
          }

          // Outer bark vs inner wood vs peeled bark
          if (dist >= r - 0.85) {
            const isPeeled = (x >= 11 && x <= 14 && y >= 8) ||
                            (x >= 22 && x <= 25 && (z <= 6 || y >= 9)) ||
                            (x >= 32 && x <= 34 && y >= 7);
            if (isPeeled) {
              set(x, y, z, strippedX());
            } else {
              set(x, y, z, logX());
            }
          } else {
            // Heartwood core
            if (x === 7 || x === 36 || x === 17 || x === 19 || x === 27 || x === 29) {
              set(x, y, z, strippedX());
            } else {
              set(x, y, z, ((x + y + z) % 3 === 0) ? planksId : strippedX());
            }
          }
        }
      }
    }
  }

  // Peeling bark flaps
  set(11, 10, 6, td('south', 'top', false));
  set(14, 10, 8, td('north', 'top', false));
  set(22, 10, 5, sl('top'));
  set(25, 9, 5, td('east', 'bottom', false));
  set(32, 9, 5, sl('bottom'));

  // Residual limb stubs on giant trunk
  set(15, 12, 8, logY());
  set(15, 13, 8, fenceId);
  set(25, 11, 6, logZ());
  set(25, 11, 5, fenceId);

  // ==========================================
  // 3. CROSSCUT BUCKING SAWS & WEDGES
  // ==========================================
  // Kerf 1 (x = 18)
  for (let z = 5; z <= 9; z++) {
    set(18, 8, z, "minecraft:iron_bars");
  }
  set(18, 8, 4, fenceId);
  set(18, 9, 4, fenceId);
  set(18, 8, 10, fenceId);
  set(18, 9, 10, fenceId);
  set(18, 11, 7, stoneSlabId);
  set(18, 12, 7, stoneSlabId);
  set(18, 11, 6, "minecraft:iron_bars");
  set(18, 11, 8, "minecraft:iron_bars");

  // Kerf 2 (x = 28)
  for (let z = 5; z <= 9; z++) {
    set(28, 9, z, "minecraft:iron_bars");
  }
  set(28, 9, 4, fenceId);
  set(28, 10, 4, fenceId);
  set(28, 9, 10, fenceId);
  set(28, 10, 10, fenceId);
  set(28, 11, 6, stoneSlabId);
  set(28, 12, 6, stoneSlabId);
  set(28, 11, 8, stoneSlabId);

  // ==========================================
  // 4. TIMBER CRIBBING BENTS (x = 10, 20, 30)
  // ==========================================
  const bents = [10, 20, 30];
  for (const bx of bents) {
    // Transverse header log under trunk
    for (let z = 4; z <= 10; z++) {
      set(bx, 5, z, logZ());
    }
    // Chocks
    set(bx, 6, 4, stair('south', 'bottom'));
    set(bx, 6, 10, stair('north', 'bottom'));

    // Longitudinal runners
    for (let x = bx - 1; x <= bx + 1; x++) {
      set(x, 4, 5, logX());
      set(x, 4, 9, logX());
    }

    // Lower transverse tier
    for (let z = 5; z <= 9; z++) {
      set(bx - 1, 3, z, logZ());
      set(bx + 1, 3, z, logZ());
    }

    // Pier pillars down to terrain
    for (let cx of [bx - 1, bx, bx + 1]) {
      for (let cz of [5, 7, 9]) {
        const gY = getGroundY(cx, cz);
        for (let y = gY; y <= 2; y++) {
          set(cx, y, cz, logY());
        }
      }
    }
  }

  // ==========================================
  // 5. SAWYERS' SCAFFOLDING & STAGING
  // ==========================================
  const scaffoldPosts = [13, 17, 21, 25, 29, 33];

  // --- North Staging (z = 3) ---
  for (let x = 12; x <= 34; x++) {
    set(x, 7, 3, planksId);
    if ((x >= 14 && x <= 16) || (x >= 20 && x <= 26) || (x >= 30 && x <= 33)) {
      set(x, 7, 4, sl('top'));
    }
    set(x, 8, 2, fenceId); // outer guardrail
    set(x, 6, 3, fenceId); // ledger rail
  }

  for (const px of scaffoldPosts) {
    const gY = getGroundY(px, 3);
    set(px, 8, 3, fenceId);
    set(px, 8, 2, fenceId);
    // Post legs down to ground
    for (let y = gY; y <= 6; y++) {
      set(px, y, 3, (y < 2) ? logY() : fenceId);
    }
    // Cross-struts tying staging to cribbing/trunk
    set(px, 6, 4, fenceId);
    set(px, 6, 5, logZ());
  }

  // North-West access stair stepping to ground
  set(12, 6, 3, stair('east', 'bottom'));
  set(11, 5, 3, stair('east', 'bottom'));
  set(10, 4, 3, stair('east', 'bottom'));
  for (let x of [10, 11, 12]) {
    const gY = getGroundY(x, 3);
    for (let y = gY; y <= 3; y++) {
      set(x, y, 3, planksId);
    }
  }

  // --- South Staging (z = 11) ---
  for (let x = 12; x <= 34; x++) {
    set(x, 7, 11, planksId);
    if ((x >= 14 && x <= 16) || (x >= 20 && x <= 26) || (x >= 30 && x <= 33)) {
      set(x, 7, 10, sl('top'));
    }
    set(x, 8, 12, fenceId); // outer guardrail
    set(x, 6, 11, fenceId); // ledger rail
  }

  for (const px of scaffoldPosts) {
    const gY = getGroundY(px, 11);
    set(px, 8, 11, fenceId);
    set(px, 8, 12, fenceId);
    // Post legs down to ground
    for (let y = gY; y <= 6; y++) {
      set(px, y, 11, (y < 2) ? logY() : fenceId);
    }
    // Cross-struts tying staging to cribbing/trunk
    set(px, 6, 10, fenceId);
    set(px, 6, 9, logZ());
  }

  // South-East access stair stepping to ground
  set(34, 6, 11, stair('west', 'bottom'));
  set(35, 5, 11, stair('west', 'bottom'));
  set(36, 4, 11, stair('west', 'bottom'));
  for (let x of [34, 35, 36]) {
    const gY = getGroundY(x, 11);
    for (let y = gY; y <= 3; y++) {
      set(x, y, 11, planksId);
    }
  }

  // ==========================================
  // 6. GIN-POLE DERRICK & ROLLWAY (x: 35..37)
  // ==========================================
  const apexX = 36, apexY = 14, apexZ = 7;
  set(apexX, apexY, apexZ, strippedY());

  // Tripod leg 1 (North)
  const gY1 = getGroundY(35, 5);
  for (let y = gY1; y <= 13; y++) {
    set(35, y, 5, (y < 4) ? logY() : fenceId);
  }
  set(35, 13, 6, fenceId);

  // Tripod leg 2 (South)
  const gY2 = getGroundY(35, 9);
  for (let y = gY2; y <= 13; y++) {
    set(35, y, 9, (y < 4) ? logY() : fenceId);
  }
  set(35, 13, 8, fenceId);

  // Tripod leg 3 (East backstay)
  const gY3 = getGroundY(37, 7);
  for (let y = gY3; y <= 13; y++) {
    set(37, y, 7, (y < 4) ? logY() : fenceId);
  }
  set(37, 14, 7, fenceId);

  // Derrick tackle
  set(apexX, 13, apexZ, "minecraft:chain[axis=y]");
  set(apexX, 12, apexZ, "minecraft:chain[axis=y]");
  set(apexX, 11, apexZ, "minecraft:chain[axis=y]");
  set(apexX, 10, apexZ, stoneWallId);

  // Lantern hanging on derrick
  set(apexX, 14, apexZ + 1, fenceId);
  set(apexX, 13, apexZ + 1, "minecraft:lantern[hanging=true]");

  // Rollway skid ramps at log end
  for (let z = 5; z <= 9; z++) {
    set(36, 5, z, logZ());
    const gY = getGroundY(37, z);
    for (let y = gY; y <= 4; y++) {
      set(37, y, z, logX());
    }
  }

  // ==========================================
  // 7. SAWDUST CONES, TOOL BENCH & DETAILS
  // ==========================================
  // Sawdust cone under Kerf 1
  for (let x = 17; x <= 19; x++) {
    for (let z = 6; z <= 8; z++) {
      const gY = getGroundY(x, z);
      for (let y = gY; y <= 5; y++) {
        set(x, y, z, (y === 5) ? sl('bottom') : planksId);
      }
    }
  }

  // Sawdust cone under Kerf 2
  for (let x = 27; x <= 29; x++) {
    for (let z = 6; z <= 8; z++) {
      const gY = getGroundY(x, z);
      for (let y = gY; y <= 5; y++) {
        set(x, y, z, (y === 5) ? sl('bottom') : planksId);
      }
    }
  }

  // Bark shavings on ground near peeled zones
  for (let x = 12; x <= 14; x++) {
    set(x, getGroundY(x, 5), 5, sl('bottom'));
    set(x, getGroundY(x, 9), 9, sl('bottom'));
  }
  for (let x = 23; x <= 25; x++) {
    set(x, getGroundY(x, 5), 5, sl('bottom'));
    set(x, getGroundY(x, 9), 9, sl('bottom'));
  }

  // Tool bench on North staging
  set(23, 8, 3, "minecraft:barrel[facing=up]");
  set(24, 8, 3, sl('bottom'));
  set(23, 9, 3, fenceId);
  set(23, 10, 3, fenceId);
  set(23, 10, 4, fenceId);
  set(23, 9, 4, "minecraft:lantern[hanging=true]");

  return {
    name: "felled_colossal_redwood",
    seatY: SEAT_Y,
    anchors: {
      front: [19, 4, 0],
      stump: [3, 9, 7],
      rigging: [36, 4, 7],
      platform_north: [23, 7, 3],
      platform_south: [23, 7, 11]
    }
  };
}

steam_donkey_rig.source:
export const envelope = [16, 20, 14];

export default function build(api) {
  const [W, H, D] = api.size;

  // Safe block setter with bounds clipping
  const placed = new Map();
  function set(x, y, z, block) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    api.set(x, y, z, block);
    placed.set(`${x},${z}`, Math.min(placed.get(`${x},${z}`) ?? y, y));
  }

  // Theme extractions & fallbacks
  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_spruce_log";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const woodStairs = api.theme.wood.stairs || "minecraft:spruce_stairs";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:spruce_trapdoor";
  const stonePrimary = api.theme.stone.primary || "minecraft:deepslate_bricks";
  const stoneAccent = api.theme.stone.accent || "minecraft:polished_deepslate";
  const stoneSlab = api.theme.stone.slab || "minecraft:polished_deepslate_slab";
  const stoneStairs = api.theme.stone.stairs || "minecraft:polished_deepslate_stairs";
  const stoneWall = api.theme.stone.wall || "minecraft:deepslate_brick_wall";

  // State formatting helpers
  function baseName(blockStr) {
    const idx = blockStr.indexOf('[');
    return idx === -1 ? blockStr : blockStr.slice(0, idx);
  }
  function st(blockStr, states) {
    return `${baseName(blockStr)}[${states}]`;
  }
  function slab(blockStr, type = "bottom") {
    return `${baseName(blockStr)}[type=${type}]`;
  }
  function axis(blockStr, ax = "y") {
    return `${baseName(blockStr)}[axis=${ax}]`;
  }

  // Linear 3D continuous cable/line interpolator
  function drawLine(x0, y0, z0, x1, y1, z1, block) {
    const dx = x1 - x0;
    const dy = y1 - y0;
    const dz = z1 - z0;
    const steps = Math.max(Math.abs(dx), Math.abs(dy), Math.abs(dz)) * 2;
    for (let i = 0; i <= steps; i++) {
      const t = steps === 0 ? 0 : i / steps;
      set(x0 + dx * t, y0 + dy * t, z0 + dz * t, block);
    }
  }

  // 1. SLED RUNNERS & SKID FRAMEWORK
  // Main engine sled runners (Left at X=2, Right at X=8)
  for (let z = 1; z <= 12; z++) {
    set(2, 1, z, axis(woodLog, "z"));
    set(8, 1, z, axis(woodLog, "z"));
  }
  // Upcurved sled horns at ends for pulling over stumps
  set(2, 2, 1, axis(woodLog, "z"));
  set(8, 2, 1, axis(woodLog, "z"));
  set(2, 2, 12, axis(woodLog, "z"));
  set(8, 2, 12, axis(woodLog, "z"));

  // Derrick sled runners (Inner at X=11, Outer at X=14)
  for (let z = 2; z <= 12; z++) {
    set(11, 1, z, axis(woodLog, "z"));
    set(14, 1, z, axis(woodLog, "z"));
  }
  set(11, 2, 2, axis(woodLog, "z"));
  set(14, 2, 2, axis(woodLog, "z"));
  set(11, 2, 12, axis(woodLog, "z"));
  set(14, 2, 12, axis(woodLog, "z"));

  // Heavy cross-tie bunks connecting donkey sled to derrick platform
  const crossZ = [2, 5, 8, 11];
  for (const z of crossZ) {
    for (let x = 2; x <= 14; x++) {
      set(x, 1, z, axis(woodLog, "x"));
    }
  }

  // Engine deck planks
  for (let z = 3; z <= 11; z++) {
    for (let x = 3; x <= 7; x++) {
      set(x, 1, z, woodPlanks);
    }
  }

  // Derrick deck planks
  for (let z = 3; z <= 9; z++) {
    for (let x = 11; x <= 14; x++) {
      set(x, 1, z, woodPlanks);
    }
  }

  // 2. VERTICAL BOILER & SMOKESTACK (Center at X=5, Z=9)
  // Firebox base (Y=2)
  for (let x = 4; x <= 6; x++) {
    for (let z = 8; z <= 10; z++) {
      set(x, 2, z, stonePrimary);
    }
  }
  set(5, 2, 8, "minecraft:blast_furnace[facing=north]");
  set(4, 2, 8, stoneAccent);
  set(6, 2, 8, stoneAccent);
  set(4, 2, 10, stoneAccent);
  set(6, 2, 10, stoneAccent);

  // Boiler cylindrical iron pressure vessel (Y=3..5)
  for (let y = 3; y <= 5; y++) {
    set(5, y, 9, "minecraft:iron_block");
    set(4, y, 9, "minecraft:iron_block");
    set(6, y, 9, "minecraft:iron_block");
    set(5, y, 8, "minecraft:iron_block");
    set(5, y, 10, "minecraft:iron_block");
    set(4, y, 8, stoneWall);
    set(6, y, 8, stoneWall);
    set(4, y, 10, stoneWall);
    set(6, y, 10, stoneWall);
  }

  // Boiler crown dome (Y=6)
  set(5, 6, 9, "minecraft:iron_block");
  set(4, 6, 9, st(stoneStairs, "facing=east,half=bottom"));
  set(6, 6, 9, st(stoneStairs, "facing=west,half=bottom"));
  set(5, 6, 8, st(stoneStairs, "facing=south,half=bottom"));
  set(5, 6, 10, st(stoneStairs, "facing=north,half=bottom"));

  // Dome cap (Y=7)
  set(5, 7, 9, slab(stoneSlab, "bottom"));
  set(4, 7, 9, slab(stoneSlab, "bottom"));
  set(6, 7, 9, slab(stoneSlab, "bottom"));
  set(5, 7, 8, "minecraft:lightning_rod[facing=up]"); // Steam relief valve

  // Smokestack with spark arrestor (Y=8..12)
  set(5, 8, 9, stoneAccent);
  set(5, 9, 9, stoneWall);
  set(5, 10, 9, stoneWall);
  set(5, 11, 9, "minecraft:hopper[facing=down]");
  set(5, 12, 9, "minecraft:campfire[lit=true]"); // Live logging camp smoke

  // Boiler fittings
  set(4, 4, 8, "minecraft:tripwire_hook[facing=north]"); // Water level sight
  set(3, 4, 9, "minecraft:lever[face=wall,facing=west]"); // Blowoff valve

  // 3. STEAM DRIVE CYLINDERS & DUAL WINCH DRUMS
  // Twin horizontal steam pistons (Flanking on X=2 and X=8)
  set(2, 2, 5, "minecraft:blast_furnace[facing=north]");
  set(2, 2, 4, "minecraft:dispenser[facing=north]");
  set(2, 2, 3, "minecraft:lightning_rod[facing=north]"); // Piston connecting rod
  set(8, 2, 5, "minecraft:blast_furnace[facing=north]");
  set(8, 2, 4, "minecraft:dispenser[facing=north]");
  set(8, 2, 3, "minecraft:lightning_rod[facing=north]");

  // Main Yarding Drum (Heavy mainline winch, Z=4)
  set(3, 2, 4, stoneAccent);
  set(7, 2, 4, stoneAccent);
  set(3, 3, 4, "minecraft:grindstone[face=wall,facing=north]"); // Bull gear
  set(7, 3, 4, "minecraft:grindstone[face=wall,facing=north]");
  for (let x = 4; x <= 6; x++) {
    set(x, 2, 4, "minecraft:iron_block");
    set(x, 3, 4, "minecraft:iron_block");
    set(x, 4, 4, "minecraft:chain[axis=x]");
    set(x, 3, 3, "minecraft:chain[axis=x]");
    set(x, 3, 5, "minecraft:chain[axis=x]");
  }

  // Haulback Drum (Secondary return winch, Z=6)
  set(3, 2, 6, stoneAccent);
  set(7, 2, 6, stoneAccent);
  set(3, 3, 6, "minecraft:grindstone[face=wall,facing=north]");
  set(7, 3, 6, "minecraft:grindstone[face=wall,facing=north]");
  for (let x = 4; x <= 6; x++) {
    set(x, 2, 6, axis(woodStripped, "x"));
    set(x, 3, 6, "minecraft:iron_block");
    set(x, 4, 6, "minecraft:chain[axis=x]");
  }

  // Steam supply piping from boiler to drive cylinders
  set(4, 5, 8, "minecraft:iron_bars");
  set(3, 5, 8, "minecraft:iron_bars");
  set(3, 4, 8, "minecraft:iron_bars");
  set(3, 3, 8, "minecraft:hopper[facing=down]");
  set(6, 5, 8, "minecraft:iron_bars");
  set(7, 5, 8, "minecraft:iron_bars");
  set(7, 4, 8, "minecraft:iron_bars");
  set(7, 3, 8, "minecraft:hopper[facing=down]");

  // 4. OPERATOR STATION, FUEL BUNKER & WATER TANK
  // Operator controls & throttle
  set(3, 2, 7, stoneAccent);
  set(4, 2, 7, stoneAccent);
  set(3, 3, 7, "minecraft:lever[face=floor,facing=north]");
  set(4, 3, 7, "minecraft:lever[face=floor,facing=north]");
  set(3, 2, 8, "minecraft:heavy_weighted_pressure_plate");
  set(4, 2, 8, "minecraft:heavy_weighted_pressure_plate");

  // Water cistern tank (X=3..4, Z=10..11)
  for (let y = 2; y <= 3; y++) {
    set(3, y, 10, woodPlanks);
    set(4, y, 10, woodPlanks);
    set(3, y, 11, woodPlanks);
    set(4, y, 11, woodPlanks);
  }
  set(3, 4, 10, st(woodTrapdoor, "facing=north,half=bottom"));
  set(4, 4, 10, st(woodTrapdoor, "facing=north,half=bottom"));
  set(3, 4, 11, st(woodTrapdoor, "facing=south,half=bottom"));
  set(4, 4, 11, st(woodTrapdoor, "facing=south,half=bottom"));

  // Firewood cord rack (X=6..7, Z=10..12)
  for (let z = 10; z <= 12; z++) {
    set(6, 2, z, axis(woodLog, "x"));
    set(7, 2, z, axis(woodLog, "x"));
  }
  set(6, 3, 11, axis(woodLog, "x"));
  set(7, 3, 11, axis(woodLog, "x"));
  set(6, 3, 12, axis(woodLog, "x"));
  set(7, 3, 12, axis(woodLog, "x"));
  set(6, 4, 11, slab(woodSlab, "bottom"));
  set(7, 4, 11, slab(woodSlab, "bottom"));

  // 5. ENGINE CANOPY ROOF
  // Structural timber uprights
  const postCoords = [[2, 2], [8, 2], [2, 11], [8, 11]];
  for (const [px, pz] of postCoords) {
    for (let y = 2; y <= 6; y++) {
      set(px, y, pz, woodFence);
    }
  }
  // Canopy header frame at Y=6
  for (let z = 2; z <= 11; z++) {
    set(2, 6, z, axis(woodStripped, "z"));
    set(8, 6, z, axis(woodStripped, "z"));
  }
  for (const z of [2, 5, 8, 11]) {
    for (let x = 2; x <= 8; x++) {
      set(x, 6, z, axis(woodStripped, "x"));
    }
  }
  // Roof decking at Y=7 with chimney opening
  for (let z = 2; z <= 11; z++) {
    set(1, 7, z, st(woodStairs, "facing=east,half=bottom"));
    set(9, 7, z, st(woodStairs, "facing=west,half=bottom"));
    for (let x = 2; x <= 8; x++) {
      // Keep hole clear for smokestack
      if (x >= 4 && x <= 6 && z >= 8 && z <= 10) continue;
      set(x, 7, z, slab(woodSlab, "top"));
    }
  }
  // Overhead work lantern
  set(3, 5, 6, "minecraft:lantern[hanging=true]");

  // 6. RIGGED SPAR DERRICK (Yarding Mast & Boom Rigging)
  // Central heavy redwood spar mast (X=12, Z=5, climbing Y=1..17)
  for (let y = 1; y <= 16; y++) {
    set(12, y, 5, axis(woodLog, "y"));
  }
  set(12, 17, 5, axis(woodStripped, "y"));

  // Mast footing & collar braces
  set(11, 2, 5, st(woodStairs, "facing=east,half=bottom"));
  set(13, 2, 5, st(woodStairs, "facing=west,half=bottom"));
  set(12, 2, 4, st(woodStairs, "facing=south,half=bottom"));
  set(12, 2, 6, st(woodStairs, "facing=north,half=bottom"));

  // A-frame triangulation stifflegs
  set(14, 2, 2, axis(woodLog, "y"));
  set(14, 3, 3, woodFence);
  set(13, 4, 3, woodFence);
  set(13, 5, 4, woodFence);
  set(12, 6, 4, axis(woodLog, "z"));

  set(14, 2, 9, axis(woodLog, "y"));
  set(14, 3, 8, woodFence);
  set(13, 4, 7, woodFence);
  set(13, 5, 6, woodFence);
  set(12, 6, 6, axis(woodLog, "z"));

  set(11, 2, 9, axis(woodLog, "y"));
  set(11, 3, 8, woodFence);
  set(11, 4, 7, woodFence);
  set(12, 5, 6, woodFence);

  // Mid-mast guide collar (Y=10)
  set(11, 10, 5, woodFence);
  set(13, 10, 5, woodFence);
  set(12, 10, 4, woodFence);
  set(12, 10, 6, woodFence);

  // Masthead crown collar & Bull Block Sheave (Y=16)
  set(11, 16, 5, st(woodTrapdoor, "facing=west,half=top"));
  set(13, 16, 5, st(woodTrapdoor, "facing=east,half=top"));
  set(12, 16, 6, st(woodTrapdoor, "facing=south,half=top"));
  set(12, 16, 4, "minecraft:hopper[facing=south]"); // Main high-lead sheave

  // 7. CABLES & GUY WIRE RIGGING (Chains)
  // Mainline cable: Winch drum (5,4,4) -> Bull Block (12,16,4)
  drawLine(5, 4, 4, 12, 16, 4, "minecraft:chain");

  // Yarding line: Bull Block (12,16,4) -> Clearcut Log Landing (8,5,0)
  drawLine(12, 16, 4, 8, 5, 0, "minecraft:chain");
  set(8, 4, 0, "minecraft:chain");
  set(8, 3, 0, "minecraft:tripwire_hook[facing=south]"); // Choker hook

  // Masthead Guy Wires (Tensioned backstays)
  drawLine(12, 17, 5, 14, 2, 11, "minecraft:chain"); // Rear-East guy line
  drawLine(12, 17, 5, 15, 2, 5, "minecraft:chain");  // East outrigger guy line
  drawLine(12, 17, 5, 8, 2, 12, "minecraft:chain");  // West anchor guy line

  // Sled outrigger anchor blocks
  set(15, 1, 5, axis(woodLog, "z"));
  set(15, 2, 5, stoneAccent);

  // 8. GIANT REDWOOD LOG AT LANDING (North edge facing clearcut)
  for (let x = 6; x <= 10; x++) {
    set(x, 1, 0, axis(woodLog, "x"));
    set(x, 1, 1, axis(woodLog, "x"));
    if (x >= 7 && x <= 9) {
      set(x, 2, 0, axis(woodLog, "x"));
      set(x, 2, 1, axis(woodLog, "x"));
    }
  }
  // Choker cable looped around the timber log
  set(8, 3, 0, "minecraft:chain");
  set(8, 2, 0, "minecraft:chain");
  set(8, 2, 1, "minecraft:chain");

  // 9. LOGGING RIG WORKSHOP PROPS & DETAILS
  // Sled tow bridle on forward horns
  set(3, 2, 1, "minecraft:chain");
  set(4, 2, 1, "minecraft:chain");
  set(6, 2, 1, "minecraft:chain");
  set(7, 2, 1, "minecraft:chain");
  set(5, 2, 1, "minecraft:iron_block");

  // Lubricant tubs, anvil, and maintenance tools
  set(2, 2, 8, "minecraft:anvil[facing=north]");
  set(8, 2, 8, "minecraft:cauldron");
  set(2, 2, 9, st(woodTrapdoor, "facing=east,half=bottom"));
  set(8, 2, 7, woodFence);
  set(8, 3, 7, "minecraft:lantern[hanging=false]");

  // Cant hook levers on skid flank
  set(1, 2, 4, "minecraft:lever[face=wall,facing=west]");
  set(1, 2, 7, "minecraft:lever[face=wall,facing=west]");

  // 10. GROUND CONFORMANCE (Rule 6: Robust cribbing down to terrain)
  // Ensure heavy timber foundation / cribbing fills down to actual ground everywhere
  for (const [key, minY] of placed.entries()) {
    const [x, z] = key.split(",").map(Number);
    const ground = Math.round(api.heightAt(x, z));
    if (ground < minY) {
      for (let y = minY - 1; y >= ground; y--) {
        // Alternating stacked cribbing logs
        if (Math.abs(y) % 2 === 0) {
          set(x, y, z, axis(woodLog, "x"));
        } else {
          set(x, y, z, axis(woodLog, "z"));
        }
      }
    }
  }

  return {
    name: "Steam Donkey Logging Rig",
    seatY: 0,
    anchors: {
      front: [8, 1, 0],
      operator: [3, 2, 7],
      boiler: [5, 2, 9],
      spar: [12, 1, 5]
    }
  };
}

hollow_stump_workshop.source:
export const envelope = [11, 10, 11];

export default function build(api) {
  const [W, H, D] = api.size;
  const inst = api.instance.index % 4;
  const rng = api.random;

  // Safe bounded block placement helper
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D && block) {
      api.set(x, y, z, block);
    }
  }

  // Safe block state helper
  function applyState(base, stateStr) {
    if (!base) return base;
    const bracket = base.indexOf('[');
    const name = bracket === -1 ? base : base.slice(0, bracket);
    return `${name}[${stateStr}]`;
  }

  // World Theme palette with fallbacks
  const woodLog = api.theme.wood.log;
  const woodStripped = api.theme.wood.stripped || woodLog;
  const woodPlanks = api.theme.wood.planks;
  const woodStairs = api.theme.wood.stairs || woodPlanks;
  const woodSlab = api.theme.wood.slab || woodPlanks;
  const woodFence = api.theme.wood.fence;
  const woodDoor = api.theme.wood.door;
  const woodTrapdoor = api.theme.wood.trapdoor;

  const stonePrimary = api.theme.stone.primary;
  const stoneAccent = api.theme.stone.accent || stonePrimary;
  const stoneStairs = api.theme.stone.stairs || stonePrimary;
  const stoneSlab = api.theme.stone.slab || stonePrimary;
  const stoneWall = api.theme.stone.wall || stonePrimary;

  const groundPavement = api.theme.ground.pavement || stonePrimary;
  const groundScree = api.theme.ground.scree || groundPavement;

  const roofStairs = api.theme.roof.stairs || woodStairs;
  const roofSlab = api.theme.roof.slab || woodSlab;
  const roofSolid = api.theme.roof.solid || woodPlanks;

  // Prepared block state strings
  const logY = applyState(woodLog, "axis=y");
  const logX = applyState(woodLog, "axis=x");
  const logZ = applyState(woodLog, "axis=z");
  const strippedY = applyState(woodStripped, "axis=y");
  const strippedX = applyState(woodStripped, "axis=x");
  const strippedZ = applyState(woodStripped, "axis=z");

  function wStairs(facing, half = "bottom") {
    return applyState(woodStairs, `facing=${facing},half=${half},shape=straight`);
  }
  function sStairs(facing, half = "bottom") {
    return applyState(stoneStairs, `facing=${facing},half=${half},shape=straight`);
  }
  function rStairs(facing, half = "bottom") {
    return applyState(roofStairs, `facing=${facing},half=${half},shape=straight`);
  }
  function wSlab(type = "bottom") {
    return applyState(woodSlab, `type=${type}`);
  }
  function sSlab(type = "bottom") {
    return applyState(stoneSlab, `type=${type}`);
  }
  function rSlab(type = "bottom") {
    return applyState(roofSlab, `type=${type}`);
  }
  function wTrapdoor(facing = "north", half = "bottom", open = false) {
    return applyState(woodTrapdoor, `facing=${facing},half=${half},open=${open}`);
  }

  // Geometry configuration
  const cx = 5.0;
  const cz = 5.0;
  const stumpTopY = inst === 1 || inst === 3 ? 6 : 5;
  const innerR = 2.15;

  // Buttress root angles per instance
  let baseAngles;
  if (inst === 0) baseAngles = [0.6, 2.1, 3.7, 5.2];
  else if (inst === 1) baseAngles = [0.4, 1.7, 3.0, 4.3, 5.5];
  else if (inst === 2) baseAngles = [0.8, 2.3, 3.9, 5.4];
  else baseAngles = [0.3, 1.6, 2.8, 4.1, 5.3];

  const rootAngles = baseAngles.map(a => a + (rng() - 0.5) * 0.15);

  function getOuterRadius(y, angle) {
    const yProg = Math.max(0, Math.min(1, y / stumpTopY));
    const baseR = 3.5 + (inst === 1 ? 0.2 : 0);
    const trunkR = baseR * (1 - yProg * 0.2);

    let rootBoost = 0;
    for (const ra of rootAngles) {
      const diff = Math.abs((angle - ra + Math.PI * 3) % (Math.PI * 2) - Math.PI);
      if (diff < 0.85) {
        const f = Math.cos(diff * (Math.PI / 1.7));
        if (f > 0) {
          rootBoost = Math.max(rootBoost, Math.pow(f, 2.2));
        }
      }
    }

    const flareDecay = Math.max(0, 1.0 - y / 3.8);
    return trunkR + rootBoost * 1.5 * flareDecay;
  }

  // 1. Terrain skirt and deep foundation downwards (Rule 6)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.hypot(dx, dz);
      const angle = Math.atan2(dz, dx);
      const outerR0 = getOuterRadius(0, angle);
      const isDoorway = (Math.abs(dx) <= 0.8 && z >= 0 && z <= cz);

      if (dist <= outerR0 + 0.3 || isDoorway) {
        const gh = Math.round(api.heightAt(x, z));
        if (gh < 0) {
          for (let fy = -1; fy >= gh; fy--) {
            if (dist < innerR && !isDoorway) {
              set(x, fy, z, groundScree);
            } else if (isDoorway) {
              set(x, fy, z, groundPavement);
            } else {
              set(x, fy, z, logY);
            }
          }
        }
      }
    }
  }

  // 2. Build the colossal severed redwood trunk
  for (let y = 0; y <= stumpTopY; y++) {
    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.hypot(dx, dz);
        const angle = Math.atan2(dz, dx);
        const outerR = getOuterRadius(y, angle);

        if (dist <= outerR) {
          // Inside hollow
          if (dist < innerR) {
            if (y === 0) {
              // Floor inside
              set(x, 0, z, (x + z) % 2 === 0 ? woodPlanks : strippedY);
            }
          } else {
            // Trunk wall
            const isOuterBark = (dist >= outerR - 0.7);
            if (y === stumpTopY) {
              // Severed cut surface shows annular rings
              if (isOuterBark) {
                set(x, y, z, logY);
              } else {
                set(x, y, z, strippedY);
              }
            } else {
              set(x, y, z, isOuterBark ? logY : strippedY);
            }
          }
        }
      }
    }
  }

  // 3. Carve North doorway & threshold
  // Clear corridor at z = 1..3, x = 5, y = 1..3
  for (let z = 1; z <= 3; z++) {
    set(5, 0, z, woodPlanks);
    set(5, 1, z, "minecraft:air");
    set(5, 2, z, "minecraft:air");
    set(5, 3, z, "minecraft:air");
  }

  // Door jambs
  set(4, 1, 2, logY);
  set(4, 2, 2, logY);
  set(4, 3, 2, logY);
  set(6, 1, 2, logY);
  set(6, 2, 2, logY);
  set(6, 3, 2, logY);
  set(5, 3, 2, wStairs("south", "top"));

  // Functional timber door
  set(5, 1, 3, applyState(woodDoor, "facing=north,half=lower,open=false,hinge=left"));
  set(5, 2, 3, applyState(woodDoor, "facing=north,half=upper,open=false,hinge=left"));

  // Entrance approach step on slope
  const frontGh = Math.round(api.heightAt(5, 0));
  if (frontGh < 0) {
    set(5, 0, 0, sStairs("south", "bottom"));
    for (let fy = -1; fy >= frontGh; fy--) {
      set(5, fy, 0, groundPavement);
    }
  }

  // 4. Instance-specific Workshop Superstructure & Attachments
  let instanceName = "";
  let interiorKind = "workshop";

  if (inst === 0) {
    // === SAW-FILING SHACK ===
    instanceName = "Hollow Stump Saw-Filing Shack";
    interiorKind = "workshop";

    // Sloped lean-to timber roof over the severed stump
    // South high (z=7,8), North low (z=2,3)
    for (let x = 3; x <= 7; x++) {
      set(x, stumpTopY + 2, 7, rSlab("top"));
      set(x, stumpTopY + 2, 6, rStairs("north"));
      set(x, stumpTopY + 1, 5, rStairs("north"));
      set(x, stumpTopY + 1, 4, rStairs("north"));
      set(x, stumpTopY + 1, 3, rSlab("bottom"));
    }
    // Eaves overhang over doorway
    for (let x = 4; x <= 6; x++) {
      set(x, stumpTopY, 2, wStairs("north"));
    }

    // Masonry grinding stovepipe / forge stack on East wall (x=8, z=5)
    for (let y = 1; y <= 5; y++) {
      set(8, y, 5, (y % 2 === 0) ? stoneAccent : stonePrimary);
    }
    set(8, 6, 5, stoneWall);
    set(8, 7, 5, stoneWall);
    set(8, 8, 5, stoneWall);

    // Front canopy and hanging lantern over entrance
    set(5, 4, 1, wSlab("bottom"));
    set(5, 3, 1, woodFence);
    set(5, 2, 1, "minecraft:lantern[hanging=true]");

  } else if (inst === 1) {
    // === CAMP POWDER MAGAZINE ===
    instanceName = "Hollow Stump Powder Magazine";
    interiorKind = "vault";

    // Heavy reinforced stone & log roof
    for (let x = 3; x <= 7; x++) {
      for (let z = 3; z <= 7; z++) {
        const d = Math.hypot(x - cx, z - cz);
        if (d >= 2.0 && d <= 3.2) {
          set(x, stumpTopY + 1, z, stoneWall);
        }
      }
    }
    // Heavy log crossbeams
    set(5, stumpTopY, 4, logZ);
    set(5, stumpTopY, 5, logZ);
    set(5, stumpTopY, 6, logZ);
    set(4, stumpTopY, 5, logX);
    set(6, stumpTopY, 5, logX);

    // Stone blast cap
    for (let x = 4; x <= 6; x++) {
      for (let z = 4; z <= 6; z++) {
        set(x, stumpTopY + 1, z, stoneSlab);
      }
    }
    set(5, stumpTopY + 2, 5, sSlab("bottom"));

    // Base stone reinforcement courses
    for (let x = 2; x <= 8; x++) {
      for (let z = 2; z <= 8; z++) {
        const d = Math.hypot(x - cx, z - cz);
        if (d >= 3.4 && d <= 4.6 && (x + z) % 3 === 0) {
          set(x, 1, z, sStairs("south", "bottom"));
        }
      }
    }

    // Stout stone arch framing entrance
    set(4, 3, 2, sStairs("east", "top"));
    set(6, 3, 2, sStairs("west", "top"));
    set(6, 3, 1, "minecraft:lantern[hanging=false]");

  } else if (inst === 2) {
    // === RIGGING & GREASE SHED ===
    instanceName = "Hollow Stump Rigging & Grease Shed";
    interiorKind = "workshop";

    // Gable timber roof spanning East-West
    // Ridge at z=5, y=stumpTopY+2
    for (let x = 3; x <= 7; x++) {
      set(x, stumpTopY + 2, 5, logX);
      set(x, stumpTopY + 2, 4, rStairs("north"));
      set(x, stumpTopY + 1, 3, rStairs("north"));
      set(x, stumpTopY + 2, 6, rStairs("south"));
      set(x, stumpTopY + 1, 7, rStairs("south"));
    }
    // Gable end ventilation trussing
    set(3, stumpTopY + 1, 5, woodFence);
    set(7, stumpTopY + 1, 5, woodFence);

    // Winch spar / rigging boom extending over entrance
    set(5, 4, 2, logZ);
    set(5, 4, 1, logZ);
    set(5, 5, 2, woodFence);
    set(5, 3, 1, "minecraft:chain");
    set(5, 2, 1, "minecraft:lantern[hanging=true]");

    // Exterior timber staging rack on West side
    set(2, 0, 4, strippedZ);
    set(2, 0, 5, strippedZ);
    set(2, 0, 6, strippedZ);
    set(2, 1, 5, strippedZ);
    set(1, 1, 4, woodFence);
    set(1, 1, 6, woodFence);

  } else {
    // === FELLERS' BOTHY & TOOL STORE ===
    instanceName = "Hollow Stump Fellers' Bothy";
    interiorKind = "hall";

    // Conical bark shingle cap with smoke vent
    // Outer ring of stairs
    for (let x = 3; x <= 7; x++) {
      set(x, stumpTopY + 1, 3, rStairs("south"));
      set(x, stumpTopY + 1, 7, rStairs("north"));
    }
    for (let z = 4; z <= 6; z++) {
      set(3, stumpTopY + 1, z, rStairs("east"));
      set(7, stumpTopY + 1, z, rStairs("west"));
    }

    // Mid cap ring
    set(4, stumpTopY + 2, 4, rSlab("bottom"));
    set(6, stumpTopY + 2, 4, rSlab("bottom"));
    set(4, stumpTopY + 2, 6, rSlab("bottom"));
    set(6, stumpTopY + 2, 6, rSlab("bottom"));
    set(5, stumpTopY + 2, 4, rStairs("south"));
    set(5, stumpTopY + 2, 6, rStairs("north"));
    set(4, stumpTopY + 2, 5, rStairs("east"));
    set(6, stumpTopY + 2, 5, rStairs("west"));

    // Smoke flue cap
    set(4, stumpTopY + 3, 5, woodFence);
    set(6, stumpTopY + 3, 5, woodFence);
    set(5, stumpTopY + 3, 5, rSlab("bottom"));

    // Cobblestone hearth chimney bump-out on West (x=2, z=5)
    for (let y = 0; y <= 5; y++) {
      set(2, y, 4, stonePrimary);
      set(2, y, 5, stoneAccent);
      set(2, y, 6, stonePrimary);
    }
    set(2, 6, 5, stoneWall);
    set(2, 7, 5, stoneWall);
    set(2, 8, 5, stoneWall);

    // Front porch canopy
    set(4, 3, 1, wSlab("top"));
    set(5, 3, 1, wSlab("top"));
    set(6, 3, 1, wSlab("top"));
    set(4, 2, 1, woodFence);
    set(6, 2, 1, woodFence);
    set(5, 2, 1, "minecraft:lantern[hanging=true]");
  }

  // 5. Ensure Interior Hollow is clear for fit-out compiler
  const roomMin = [4, 1, 4];
  const roomMax = [6, 3, 6];

  for (let rx = roomMin[0]; rx <= roomMax[0]; rx++) {
    for (let ry = roomMin[1]; ry <= roomMax[1]; ry++) {
      for (let rz = roomMin[2]; rz <= roomMax[2]; rz++) {
        set(rx, ry, rz, "minecraft:air");
      }
    }
  }

  return {
    name: instanceName,
    seatY: 0,
    anchors: {
      front: [5, 1, 0],
      door: [5, 1, 2]
    },
    interiors: [
      {
        min: roomMin,
        max: roomMax,
        kind: interiorKind
      }
    ]
  };
}
